import{_ as d}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{L as r,x as e,A as i,G as a,M as o,Z as h,B as n}from"./chunks/runtime-core.esm-bundler.BPWg86ya.js";const s="/assets/%E4%B8%9C%E6%A5%BC%E4%B8%80%E5%8F%B7%E4%BD%8D.DnAz3xQL.png",c="/assets/%E5%8F%98%E7%94%B5%E7%AB%99%E4%B8%80%E5%8F%B7%E4%BD%8D.BHEnz2lb.png",b="/assets/%E8%A5%BF%E6%A5%BC%E4%B8%80%E5%8F%B7%E4%BD%8D.DlfucrKH.png",u="/assets/%E5%9D%9D%E9%A1%B6%E5%A4%8D%E6%B4%BB.CKXzQ274.png",p="/assets/%E6%B8%B8%E5%AE%A2%E4%B8%AD%E5%BF%83%E4%B8%80%E5%8F%B7%E4%BD%8D.Cp_ekgh8.png",_="/assets/%E6%B0%B4%E6%B3%A5%E5%8E%82%E9%99%84%E8%BF%91.BP8IETIT.png",q="/assets/%E5%A4%A7%E7%94%B5%E4%B8%80%E5%8F%B7%E4%BD%8D.T5GRvoQu.png",y=JSON.parse('{"title":"三角洲行动攻略总结","description":"","frontmatter":{},"headers":[],"relativePath":"column/CommonSense/生活常识/三角洲行动攻略总结.md","filePath":"column/CommonSense/生活常识/三角洲行动攻略总结.md","lastUpdated":1792133843000}'),m={name:"column/CommonSense/生活常识/三角洲行动攻略总结.md"};function k(f,t,E,B,g,x){const l=r("ArticleMetadata");return i(),e("div",null,[t[0]||(t[0]=a("h1",{id:"三角洲行动攻略总结",tabindex:"-1"},[n("三角洲行动攻略总结 "),a("a",{class:"header-anchor",href:"#三角洲行动攻略总结","aria-label":'Permalink to "三角洲行动攻略总结"'},"​")],-1)),o(l),t[1]||(t[1]=h('<nav class="table-of-contents"><ul><li><a href="#一、烽火地带">一、烽火地带</a><ul><li><a href="#_1-跑刀推荐-基础配装">1. 跑刀推荐（基础配装）</a></li><li><a href="#_2-各复活点跑图路线">2. 各复活点跑图路线</a></li><li><a href="#_3-各地图必吃物资点">3. 各地图必吃物资点</a></li></ul></li><li><a href="#二、战场模式操作">二、战场模式操作</a></li><li><a href="#三、改枪心得">三、改枪心得</a></li><li><a href="#四、裸枪最佳性价比属性-阈值">四、裸枪最佳性价比属性（阈值）</a></li><li><a href="#五、枪械等级-级别越高越贵">五、枪械等级（级别越高越贵）</a></li><li><a href="#六、子弹等级-1–6-级">六、子弹等级（1–6 级）</a></li><li><a href="#七、常见黑话速查">七、常见黑话速查</a></li><li><a href="#八、撤离方式速查">八、撤离方式速查</a></li></ul></nav><blockquote><p>本文整理了《三角洲行动》中「烽火地带」模式的跑图路线、必吃物资点，以及战场模式操作、改枪思路、枪械与子弹的性价比心得。</p><p>官方地图资源：<a href="https://df.qq.com/cp/a20240729directory" target="_blank" rel="noreferrer">三角洲行动地图目录</a></p></blockquote><h2 id="一、烽火地带" tabindex="-1">一、烽火地带 <a class="header-anchor" href="#一、烽火地带" aria-label="Permalink to &quot;一、烽火地带&quot;">​</a></h2><h3 id="_1-跑刀推荐-基础配装" tabindex="-1">1. 跑刀推荐（基础配装） <a class="header-anchor" href="#_1-跑刀推荐-基础配装" aria-label="Permalink to &quot;1. 跑刀推荐（基础配装）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>推荐</th></tr></thead><tbody><tr><td>干员</td><td>威龙</td></tr><tr><td>胸挂</td><td>17 格（DRC 先进侦查包）</td></tr><tr><td>背包</td><td>15 格（露营背包）</td></tr><tr><td>手枪</td><td>G18</td></tr><tr><td>药品</td><td>强效注射器 ×2、止痛药 ×1、止血带 ×1</td></tr><tr><td>子弹</td><td>手枪弹 3 级，保证 30 发</td></tr><tr><td>房卡</td><td>只推荐 3 张：水泥厂办公室、变电站技术室、变电站宿舍</td></tr></tbody></table><blockquote><p>枪械中最贵的是 <strong>M250</strong>。</p></blockquote><h3 id="_2-各复活点跑图路线" tabindex="-1">2. 各复活点跑图路线 <a class="header-anchor" href="#_2-各复活点跑图路线" aria-label="Permalink to &quot;2. 各复活点跑图路线&quot;">​</a></h3><h4 id="_1-东楼一号位" tabindex="-1">① 东楼一号位 <a class="header-anchor" href="#_1-东楼一号位" aria-label="Permalink to &quot;① 东楼一号位&quot;">​</a></h4><p>直接去吃航空箱，楼上楼下都看 → 破窗后直接去集装箱，站在叉车上面可以直接喷气对着角 → 走通道到军营 → 丢包撤离。</p><blockquote><p>物资点详见 3.（3）行政楼-东楼、3.（5）军营。</p></blockquote><p><img src="'+s+'" alt="东楼一号位路线" loading="lazy"></p><h4 id="_2-小电站一号位" tabindex="-1">② 小电站一号位 <a class="header-anchor" href="#_2-小电站一号位" aria-label="Permalink to &quot;② 小电站一号位&quot;">​</a></h4><p>直接去小站，爬空调外机进二楼 → 对面房间吃航空箱 → 走地下通道到水泥厂 → 吃完水泥厂从左上角撤离。</p><blockquote><p>物资点详见 3.（2）小变电站 → 大变电站、3.（6）水泥厂。</p></blockquote><p><img src="'+c+'" alt="变电站一号位路线" loading="lazy"></p><h4 id="_3-西楼一号位" tabindex="-1">③ 西楼一号位 <a class="header-anchor" href="#_3-西楼一号位" aria-label="Permalink to &quot;③ 西楼一号位&quot;">​</a></h4><p>直奔集装箱 → 绳索走坝顶负重撤离。</p><blockquote><p>物资点详见 3.（4）行政楼-西楼。</p></blockquote><p><img src="'+b+'" alt="西楼一号位路线" loading="lazy"></p><h4 id="_4-管道内复活" tabindex="-1">④ 管道内复活 <a class="header-anchor" href="#_4-管道内复活" aria-label="Permalink to &quot;④ 管道内复活&quot;">​</a></h4><p>也是去集装箱，路过军营先吃盾兵、拔他的背包 → 走左边通道去集装箱区域 → 绳索走坝顶负重撤离。</p><blockquote><p>物资点详见 3.（5）军营。</p></blockquote><h4 id="_5-坝顶复活" tabindex="-1">⑤ 坝顶复活 <a class="header-anchor" href="#_5-坝顶复活" aria-label="Permalink to &quot;⑤ 坝顶复活&quot;">​</a></h4><p>从上面直奔集装箱 → 走左边通道去军营，夺舍盾兵和二楼电脑 → 丢包撤离。</p><blockquote><p>物资点详见 3.（5）军营。</p></blockquote><p><img src="'+u+'" alt="坝顶复活路线" loading="lazy"></p><h4 id="_6-游客中心一号位" tabindex="-1">⑥ 游客中心一号位 <a class="header-anchor" href="#_6-游客中心一号位" aria-label="Permalink to &quot;⑥ 游客中心一号位&quot;">​</a></h4><p>翻窗进二楼，吃完直接破窗下去 → 吃高架下面的鸟窝 → 往养护站方向走，也吃鸟窝 → 看情况是否进大变电站（尽量不去）→ 走地下通道到水泥厂，先吃二楼平台，再跳下去吃联排房 → 左下角撤离。</p><blockquote><p>物资点详见 3.（1）游客中心、3.（6）水泥厂。</p></blockquote><p><img src="'+p+'" alt="游客中心一号位路线" loading="lazy"></p><h4 id="_7-水泥厂附近-水泥厂-→-小变电站-→-游客中心" tabindex="-1">⑦ 水泥厂附近（水泥厂 → 小变电站 → 游客中心） <a class="header-anchor" href="#_7-水泥厂附近-水泥厂-→-小变电站-→-游客中心" aria-label="Permalink to &quot;⑦ 水泥厂附近（水泥厂 → 小变电站 → 游客中心）&quot;">​</a></h4><p><img src="'+_+'" alt="水泥厂附近路线" loading="lazy"></p><p>先进水泥厂，然后走地下通道到小变电站，最后从游客中心撤离。</p><blockquote><p>物资点详见 3.（6）水泥厂、3.（2）小变电站 → 大变电站、3.（1）游客中心。</p></blockquote><h4 id="_8-大电站一号位" tabindex="-1">⑧ 大电站一号位 <a class="header-anchor" href="#_8-大电站一号位" aria-label="Permalink to &quot;⑧ 大电站一号位&quot;">​</a></h4><p>直接去大电站主房间，楼上楼下都吃 → 走地下通道进水泥厂，看有没有敌人 → 去二楼吃剩饭 → 鸟窝撤离。</p><blockquote><p>物资点详见 3.（2）小变电站 → 大变电站、3.（6）水泥厂。</p></blockquote><p><img src="'+q+'" alt="大电站一号位路线" loading="lazy"></p><h3 id="_3-各地图必吃物资点" tabindex="-1">3. 各地图必吃物资点 <a class="header-anchor" href="#_3-各地图必吃物资点" aria-label="Permalink to &quot;3. 各地图必吃物资点&quot;">​</a></h3><h4 id="_1-游客中心" tabindex="-1">（1）游客中心 <a class="header-anchor" href="#_1-游客中心" aria-label="Permalink to &quot;（1）游客中心&quot;">​</a></h4><ul><li>二楼：火箭兵必吃。</li><li>破窗之后右手边三楼：茶几桌面必看。</li><li>跳楼后左侧厕所：开门有一个医疗包。</li><li>最里面的房子：桌底下的电脑机箱。</li><li>出门正北方：医疗包和展厅。</li><li>从木板翻出去后左前方露台：有一个武器箱。</li><li>野外营：左边帐篷、右侧卡车的帐篷。</li></ul><h4 id="_2-小变电站-→-大变电站" tabindex="-1">（2）小变电站 → 大变电站 <a class="header-anchor" href="#_2-小变电站-→-大变电站" aria-label="Permalink to &quot;（2）小变电站 → 大变电站&quot;">​</a></h4><ul><li>小变电站二楼第一个房间：有小保险。</li><li>一楼：有一个机箱。</li><li>对面房间：航空箱。</li><li>前往大变电站：门口是水泥车。</li><li>进去之后左边：弹药箱。</li><li>右边房间：白衣服要摸，桌面要看，两个服务器地上也要看，打死的盾兵盒子要吃。</li><li>二楼：所有桌面都要看，可能有大红。</li><li>破窗往北走：路过医疗箱吃一下。</li><li>从空调外机踩着墙跳出变电站缺口，视角左转走停车场进入东楼。</li></ul><h4 id="_3-行政楼-东楼" tabindex="-1">（3）行政楼-东楼 <a class="header-anchor" href="#_3-行政楼-东楼" aria-label="Permalink to &quot;（3）行政楼-东楼&quot;">​</a></h4><ul><li>水泥车必吃。</li><li>仓库每一个角落都要吃，仓库左边的二楼也要吃。</li><li>翻窗后正前方房间：右手边的白大褂。</li><li>最里面的书房：开门进去右转走到底还有一个小门，里面有电脑机箱；左手边桌子上会刷房卡。</li><li>走出书房后右手边：有医疗箱。</li><li>左边设备领用室：白大褂。</li><li>东楼二楼上楼后的经理室：会刷金条，小保险。</li></ul><h4 id="_4-行政楼-西楼" tabindex="-1">（4）行政楼-西楼 <a class="header-anchor" href="#_4-行政楼-西楼" aria-label="Permalink to &quot;（4）行政楼-西楼&quot;">​</a></h4><ul><li>阳台房桌子底下：有电脑箱；每个桌面都要看。</li><li>洗手池和南厕所。</li><li>拉闸房间：有一个服务器和桌面要看。</li><li>隔壁黑屋：有电脑机箱。</li><li>男厕所破窗出去后，下面集装箱：有武器箱。</li><li>西楼一楼健身房：有一个大武器箱、白大褂和服务器。</li><li>西楼地下室入口红灯区：有一个弹药箱。</li><li>地下大门敞开的房间：有一个机箱。</li><li>出房间往前：有一个电脑骇客。</li><li>从地下室到东楼的集装箱区域也要吃。</li></ul><h4 id="_5-军营" tabindex="-1">（5）军营 <a class="header-anchor" href="#_5-军营" aria-label="Permalink to &quot;（5）军营&quot;">​</a></h4><ul><li>所有帐篷和高台屋子二楼的骇客电脑都要看。</li><li>电脑附近的桌面上也可能有好东西。</li></ul><h4 id="_6-水泥厂-最肥" tabindex="-1">（6）水泥厂（最肥） <a class="header-anchor" href="#_6-水泥厂-最肥" aria-label="Permalink to &quot;（6）水泥厂（最肥）&quot;">​</a></h4><ol><li>先吃左边的水泥车。</li><li>钻洞进管道，尽头有大武器箱。</li><li>钻洞开门下楼，吃水泥厂平台下的水泥车。</li><li>往正西北方看，有一个水泥车和卷帘房；卷帘房左手边有一个暗门，里面是手提包。</li><li>出门往右后方走，上楼小道直达水泥厂二楼平台，此处有两个武器箱和航空箱。</li><li>踩住黄色的护手大跳，进入火箭兵平台，后面的大武器箱。</li><li>走边缘下瓦房，有一个鸟窝。</li><li>直接跳下去，刚好有一个房间，里面有航空箱。</li><li>出门东南方，水泥厂办公室有一个衣服和电脑机箱，踹门出去就可以撤离了。</li></ol><h2 id="二、战场模式操作" tabindex="-1">二、战场模式操作 <a class="header-anchor" href="#二、战场模式操作" aria-label="Permalink to &quot;二、战场模式操作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>按键</th><th>功能</th></tr></thead><tbody><tr><td>5</td><td>选择支援</td></tr><tr><td>鼠标中键</td><td>标记敌人</td></tr><tr><td>G</td><td>丢投掷物</td></tr><tr><td>Q / E</td><td>探头</td></tr><tr><td>C / Z</td><td>蹲 / 趴</td></tr></tbody></table><h2 id="三、改枪心得" tabindex="-1">三、改枪心得 <a class="header-anchor" href="#三、改枪心得" aria-label="Permalink to &quot;三、改枪心得&quot;">​</a></h2><ul><li><strong>子弹在准星周围晃动</strong>：找「枪身稳定性」词条，和「据枪稳定性」无关。</li><li><strong>镜头晃动</strong>：和「据枪稳定性」有关，据枪稳定性越高，开火时的镜头晃动越小。</li></ul><h2 id="四、裸枪最佳性价比属性-阈值" tabindex="-1">四、裸枪最佳性价比属性（阈值） <a class="header-anchor" href="#四、裸枪最佳性价比属性-阈值" aria-label="Permalink to &quot;四、裸枪最佳性价比属性（阈值）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>加成区间</th><th>阈值范围</th></tr></thead><tbody><tr><td>后坐力</td><td>+8 / -0</td><td>-9 / +∞</td></tr><tr><td>据枪</td><td>±8</td><td>-20 / +16</td></tr><tr><td>操控速度</td><td>±15</td><td>-30 / +28</td></tr><tr><td>腰射</td><td>±10</td><td>-40 / +∞</td></tr></tbody></table><blockquote><p>激光开启后：操纵 +6，腰射 +12。</p></blockquote><h2 id="五、枪械等级-级别越高越贵" tabindex="-1">五、枪械等级（级别越高越贵） <a class="header-anchor" href="#五、枪械等级-级别越高越贵" aria-label="Permalink to &quot;五、枪械等级（级别越高越贵）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>等级</th><th>价格</th><th>枪械</th></tr></thead><tbody><tr><td>一级</td><td>约 1w</td><td>UZI 冲锋枪、野牛冲锋枪、CAR-15 突击步枪、AKS-74U 突击步枪</td></tr><tr><td>二级</td><td>3–5w</td><td>勇士冲锋枪、SMG45 冲锋枪、MP5 冲锋枪、PTR-32 冲锋枪、SG552 突击步枪、G3 战斗步枪、QBZ95-1 突击步枪、杠杆式步枪、R93 狙击步枪</td></tr><tr><td>三级</td><td>8–13w</td><td>腾龙突击步枪、AKM 突击步枪、SCAR-H 战斗步枪、AUG 突击步枪、MCXLT 突击步枪、MK4 冲锋枪、SR-3M 突击步枪、QCQ171 冲锋枪、P90 冲锋枪、PSG-1 射手步枪、M14 射手步枪、M700 狙击步枪</td></tr><tr><td>四级</td><td>13–20w</td><td>AS-val 突击步枪、M7 战斗步枪、KC17 突击步枪、MK47 突击步枪、MP7 冲锋枪、AWM 狙击步枪</td></tr></tbody></table><h2 id="六、子弹等级-1–6-级" tabindex="-1">六、子弹等级（1–6 级） <a class="header-anchor" href="#六、子弹等级-1–6-级" aria-label="Permalink to &quot;六、子弹等级（1–6 级）&quot;">​</a></h2><ul><li><strong>4 级弹</strong>：整个游戏的性价比天花板。对 1–5 级护甲造成的伤害都是 100%，只有对 6 级甲时会衰减为 60%。</li><li><strong>3 级弹</strong>：想要去打架，子弹不能低于 3 级。</li><li><strong>5 级弹</strong>：猛攻哥专用，对 1–6 级护甲造成的伤害都是 110%。</li><li><strong>6 级弹</strong>：主要给狙击枪专用，6 级以下基本秒杀。</li></ul><h2 id="七、常见黑话速查" tabindex="-1">七、常见黑话速查 <a class="header-anchor" href="#七、常见黑话速查" aria-label="Permalink to &quot;七、常见黑话速查&quot;">​</a></h2><blockquote><p>以下为正文中出现的黑话整理，含义以本文语境为准。</p></blockquote><table tabindex="0"><thead><tr><th>黑话</th><th>含义</th></tr></thead><tbody><tr><td>跑刀</td><td>轻装跑图：不带大枪（或只带手枪），以快速搜刮物资、避开战斗为目的</td></tr><tr><td>一号位</td><td>某片区域的固定出生 / 复活位置</td></tr><tr><td>破窗</td><td>打破窗户作为进入或通过的路线</td></tr><tr><td>喷气</td><td>威龙的喷气</td></tr><tr><td>航空箱</td><td>高价值物资箱，容易开出好东西</td></tr><tr><td>小保险</td><td>小型保险箱类</td></tr><tr><td>大红</td><td>红色品质的高价值物资</td></tr><tr><td>白大褂</td><td>地图上挂有白大褂的衣服</td></tr><tr><td>骇客</td><td>可交互的电脑 / 终端类容器</td></tr><tr><td>鸟窝</td><td>地图上的一处搜刮点（鸟巢状物资点）</td></tr><tr><td>夺舍</td><td>击杀敌人后扒下并占用对方的装备</td></tr><tr><td>盾兵 / 火箭兵</td><td>地图中的特殊敌人，分别持盾、持火箭筒</td></tr><tr><td>联排房 / 瓦房</td><td>地图上的建筑类型，分别为连排房、瓦顶房</td></tr><tr><td>得吃</td><td>口语，指“要搜刮、要拿走”</td></tr></tbody></table><h2 id="八、撤离方式速查" tabindex="-1">八、撤离方式速查 <a class="header-anchor" href="#八、撤离方式速查" aria-label="Permalink to &quot;八、撤离方式速查&quot;">​</a></h2><blockquote><p>以下为正文中出现过的撤离方式汇总，具体撤离点位置以游戏内为准。</p></blockquote><table tabindex="0"><thead><tr><th>撤离方式</th><th>说明</th><th>出现路线</th></tr></thead><tbody><tr><td>常规撤离</td><td>从地图常规撤离点撤离（文中以左上角 / 左下角表示）</td><td>② 小电站、⑥ 游客中心</td></tr><tr><td>丢包撤离</td><td>丢下背包、轻装撤离</td><td>① 东楼、⑤ 坝顶</td></tr><tr><td>负重撤离</td><td>背着高负重物资、走绳索到坝顶负重撤离</td><td>③ 西楼、④ 管道内</td></tr><tr><td>鸟窝撤离</td><td>从鸟窝方向撤离</td><td>⑧ 大电站</td></tr><tr><td>踹门 / 破窗撤离</td><td>踹门或破窗直接离开</td><td>3.（6）水泥厂</td></tr></tbody></table>',68))])}const D=d(m,[["render",k]]);export{y as __pageData,D as default};
